using System;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using EchoStation.Dialogue;
using EchoStation.Memory;
using EchoStation.Persistence;
using EchoStation.Puzzles;
using EchoStation.Story;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace EchoStation.Tests.Persistence
{
 public sealed class StationSaveJsonTests
 {
  internal static StationSaveData Fresh(){var memory=new MemoryStore();memory.AddEvent("visited_valley",0,"进入入口山谷。",MemoryPriority.Low);memory.AddCharacter(new CharacterMemory("player_current_zone",CharacterMemoryKind.PlayerKnowledge,"玩家位于入口山谷。","valley"));return new StationSaveData{Player=new SavedPose(0,.05f,-35),Echo=new SavedPose(1.5f,0,-34),EchoMode="follow",Progress=new ProgressState{Events=new[]{"visited_valley"}},MemoryJson=MemoryJson.Encode(memory.CaptureSnapshot())};}
  private static string Rehash(JObject root){using(var sha=SHA256.Create())root["sha256"]=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(root["payload"].ToString(Formatting.None)))).Replace("-","").ToLowerInvariant();return root.ToString(Formatting.None);}
  [Test]public void F03_A01_EmptyRoundTripRetainsActorsClockAnd50LiteralMessages(){var s=Fresh();s.Elapsed=60;s.Flashlight=true;s.Dialogue=Enumerable.Range(1,50).Select(i=>new DialogueMessage(i,DialogueSpeaker.Player,"<b>原样"+i)).ToArray();var json=StationSaveJson.Encode(s);var read=StationSaveJson.Decode(json);Assert.That(read.Success,Is.True,read.Detail);Assert.That(read.Data.Dialogue.Length,Is.EqualTo(50));Assert.That(read.Data.Dialogue[0].Text,Is.EqualTo("<b>原样1"));Assert.That(read.Data.Elapsed,Is.EqualTo(60));Assert.That(read.Data.Flashlight,Is.True);Assert.That(json,Does.Not.Contain("fullText"));Assert.That(read.Data.Player.Z,Is.EqualTo(-35));}
  [Test]public void F03_A02_FullEvidenceRoundTripRebuildsCanonicalSummariesAndScans(){var s=Fresh();var memory=MemoryJson.Decode(s.MemoryJson).Store;foreach(var c in StationClues.All)memory.AddClue(new ClueMemory(c.Id,c.Title,c.Summary,c.Kind,c.Password,c.KeyMarker));foreach(var p in StationScript.Puzzles)memory.AddEvent(p.CompletionId,0,"玩家完成"+p.Title+"。",MemoryPriority.Critical);s.Progress=new ProgressState{Completed=StationScript.Puzzles.Select(p=>p.Id).ToArray(),Journal=StationClues.All.Select(c=>c.Id).ToArray(),Scans=new[]{"scan_mark_01","scan_lab_calibration_01"},Events=memory.Events.Select(e=>e.Id).ToArray(),CabinOpen=true,CoreOpen=true,VentOpen=true,Powered=true,VentElapsed=3};s.MemoryJson=MemoryJson.Encode(memory.CaptureSnapshot());var read=StationSaveJson.Decode(StationSaveJson.Encode(s));Assert.That(read.Success,Is.True,read.Detail);Assert.That(read.Data.Progress.Completed.Length,Is.EqualTo(6));Assert.That(read.Data.Progress.Scans.Length,Is.EqualTo(2));Assert.That(read.Data.MemoryJson,Does.Not.Contain(StationClues.All[0].FullText));}
  [Test]public void F03_A03_StrictFieldsDuplicateJavascriptAndChecksumReject(){var json=StationSaveJson.Encode(Fresh());foreach(var bad in new[]{"",json+"{}",json.Replace("\"version\":1","\"version\":1,\"version\":1"),json.Replace("\"version\"","'version'"),json.Replace("\"version\":1","\"version\":01"),json.Replace("\"flashlight\":false","\"flashlight\":true"),json.Replace("\"payload\":", "\"unknown\":0,\"payload\":"),json.Substring(0,json.Length-1)+",}"})Assert.That(StationSaveJson.Decode(bad).Success,Is.False);var root=JObject.Parse(json);((JObject)root["payload"]).Remove("echoMode");Assert.That(StationSaveJson.Decode(Rehash(root)).Success,Is.False);}
  [Test]public void F03_A04_FutureVersionIsProtectedButOldOrWrongFormatInvalid(){var json=StationSaveJson.Encode(Fresh());Assert.That(StationSaveJson.Decode(json.Replace("\"version\":1","\"version\":2")).Status,Is.EqualTo(StationReadStatus.UnsupportedVersion));Assert.That(StationSaveJson.Decode(json.Replace("\"version\":1","\"version\":0")).Status,Is.EqualTo(StationReadStatus.Invalid));Assert.That(StationSaveJson.Decode(json.Replace("echostation.station","unrelated")).Status,Is.EqualTo(StationReadStatus.Invalid));}
  [Test]public void F03_A05_PoseNanWrongModeAccessAndClockNeverEncode(){foreach(var mutate in new Action<StationSaveData>[]{s=>s.Player.X=float.NaN,s=>s.Echo.Y=float.PositiveInfinity,s=>s.Player.Z=999,s=>s.Player.Yaw=360,s=>s.EchoMode="investigate",s=>s.Elapsed=-1,s=>s.Progress.CabinOpen=true,s=>s.Progress.Zone="core",s=>s.Echo=new SavedPose(0,0,-35)}){var s=Fresh();mutate(s);Assert.Throws<ArgumentException>(()=>StationSaveJson.Encode(s));}}
  [Test]public void F03_A06_ForgedScanReceiptAndMemoryMismatchReject(){var s=Fresh();s.Progress.Journal=new[]{"scan_mark_01"};Assert.Throws<ArgumentException>(()=>StationSaveJson.Encode(s));s=Fresh();s.Progress.Events=new[]{"visited_valley","event_fake"};Assert.Throws<ArgumentException>(()=>StationSaveJson.Encode(s));s=Fresh();var memory=MemoryJson.Decode(s.MemoryJson).Store;memory.AddClue(new ClueMemory("note_maintenance_01","伪造标题","伪造摘要",MemoryClueKind.Note,"7316"));s.Progress.Journal=new[]{"note_maintenance_01"};s.MemoryJson=MemoryJson.Encode(memory.CaptureSnapshot());Assert.That(StationSaveAudit.Validate(s),Is.EqualTo("noncanonical_clue"));}
  [Test]public void F03_A07_HistoryBoundaryDuplicateNumberAndInvalidSpeakerReject(){var s=Fresh();s.Dialogue=Enumerable.Range(1,51).Select(i=>new DialogueMessage(i,DialogueSpeaker.Echo,"记录")).ToArray();Assert.Throws<ArgumentException>(()=>StationSaveJson.Encode(s));s=Fresh();s.Dialogue=new[]{new DialogueMessage(2,DialogueSpeaker.Player,"a"),new DialogueMessage(2,DialogueSpeaker.Echo,"b")};Assert.Throws<ArgumentException>(()=>StationSaveJson.Encode(s));var root=JObject.Parse(StationSaveJson.Encode(Fresh()));root["payload"]["dialogue"]=new JArray(new JObject{["number"]=1,["speaker"]="system",["text"]="x",["refusal"]=false});Assert.That(StationSaveJson.Decode(Rehash(root)).Success,Is.False);}
  [Test]public void F03_A08_EndedAndMemoryTimeAfterClockRejectWithoutMutation(){var s=Fresh();var memory=MemoryJson.Decode(s.MemoryJson).Store;memory.AddEvent("ending_seal_exit",0,"玩家选择封存撤离。",MemoryPriority.Critical);s.MemoryJson=MemoryJson.Encode(memory.CaptureSnapshot());s.Progress.Events=memory.Events.Select(e=>e.Id).ToArray();Assert.That(StationSaveAudit.Validate(s),Is.EqualTo("ended_save_forbidden"));s=Fresh();memory=MemoryJson.Decode(s.MemoryJson).Store;memory.AddEvent("event_future",2,"时间异常。");s.MemoryJson=MemoryJson.Encode(memory.CaptureSnapshot());s.Progress.Events=memory.Events.Select(e=>e.Id).ToArray();Assert.That(StationSaveAudit.Validate(s),Is.EqualTo("event_after_clock"));Assert.That(s.Elapsed,Is.Zero);}
  [Test]public void F03_A09_OversizeDepthAndRehashedWrongTypesReject(){Assert.That(StationSaveJson.Decode(new string(' ',StationSaveJson.MaximumBytes+1)).Success,Is.False);var root=JObject.Parse(StationSaveJson.Encode(Fresh()));root["payload"]["progress"]["access"]=1.5;Assert.That(StationSaveJson.Decode(Rehash(root)).Success,Is.False);root=JObject.Parse(StationSaveJson.Encode(Fresh()));root["payload"]["flashlight"]="false";Assert.That(StationSaveJson.Decode(Rehash(root)).Success,Is.False);}
 }
}
